#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /bd-wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Ticket 0699 (ADR 0081, spec 0698): the one-time steps behind POST /api/feedback. Makes the GitHub token the Worker
# posts Reports with, the five labels, puts the token on both Workers, and dates its renewal in the runbook. Run it
# again to renew the token (a year on): every stage is safe to repeat. The token never goes to a file, chat or a log.

cd "$(dirname "$0")/.." || exit 1
REPO="czAAA/bd-beads-docs"
DOCS_DIR="../bd-beads-docs"
# Nothing here is written to a file but the runbook; this keeps the library's ENV_FILE out of the repo.
ENV_FILE="/dev/null"

need_gh() {
  command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 || {
    warn "This wizard needs the GitHub CLI, logged in as the owner of $REPO: run 'gh auth login' first."
    exit 1
  }
}

# A date a year from today, on macOS or Linux, as the token's default expiry.
year_from_today() { date -v+1y +%F 2>/dev/null || date -d '+1 year' +%F; }

TOTAL_STAGES=5

banner "Feedback: the GitHub token, labels and secrets"
need_gh

stage "GitHub: the fine-grained token"
say "The Worker posts each Report as an issue in $REPO with this token. It may touch Issues there and nothing else."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: bd-beads feedback. Description: POST /api/feedback, ADR 0081."
step "Resource owner: czAAA."
step "Expiration: Custom, the date one year from today ($(year_from_today)), or the latest GitHub allows."
step "Repository access: Only select repositories → bd-beads-docs."
step "Permissions → Repository permissions → Issues: Read and write. Leave every other permission at No access."
note "Metadata: Read-only is added by GitHub on its own; that is expected."
step "Generate token, and keep the page open: the token is shown once."
ask_secret GITHUB_TOKEN "Paste the token (hidden):"
[[ -n "$GITHUB_TOKEN" ]] || { warn "No token given; run the wizard again."; exit 1; }
ask TOKEN_EXPIRES "The expiry date GitHub shows for it (YYYY-MM-DD, Enter for $(year_from_today)):"
TOKEN_EXPIRES="${TOKEN_EXPIRES:-$(year_from_today)}"
[[ "$TOKEN_EXPIRES" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] || { warn "Not a YYYY-MM-DD date: $TOKEN_EXPIRES"; exit 1; }

stage "GitHub: check the token"
say "Reading one issue of $REPO with the token, to see it is for the right repo."
status=$(curl -s -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $GITHUB_TOKEN" \
  -H 'Accept: application/vnd.github+json' "https://api.github.com/repos/$REPO/issues?per_page=1" || echo 000)
if [[ "$status" == 200 ]]; then
  printf '  %s✓ the token reads %s%s\n' "$GREEN" "$REPO" "$RESET"
else
  warn "GitHub answered $status (401: wrong token; 404: the token does not cover $REPO)."
  confirm "Go on anyway?" || exit 1
fi
pause

stage "GitHub: the five labels"
say "Each Report is labelled from-app and its kind; the dev Worker's also dev. Made with your own gh login."
label() {
  if gh label create "$1" --repo "$REPO" --color "$2" --description "$3" --force >/dev/null; then
    printf '  %s✓ label%s %s\n' "$GREEN" "$RESET" "$1"
  else
    warn "gh could not make the label $1"
    SKIPPED+=("label $1: gh label create $1 --repo $REPO --force")
  fi
}
label from-app 5319e7 "A Report sent from the app's Feedback sheet"
label feedback 0e8a16 "Report kind: general feedback"
label translation 1d76db "Report kind: a translation problem"
label bead-color d93f0b "Report kind: a wrong or missing bead color"
label dev cccccc "Sent from the dev Worker: a test"
pause

stage "Cloudflare: GITHUB_TOKEN on both Workers"
say "Sending the token to the dev and production Workers as the secret GITHUB_TOKEN (needs 'npx wrangler login')."
for env in dev production; do
  if printf '%s' "$GITHUB_TOKEN" | npx wrangler secret put GITHUB_TOKEN --env "$env" >/dev/null; then
    WRITTEN_SECRET+=("GITHUB_TOKEN ($env Worker)")
    printf '  %s✓ set%s GITHUB_TOKEN on the %s Worker\n' "$GREEN" "$RESET" "$env"
  else
    warn "wrangler could not set GITHUB_TOKEN for $env (is the Worker deployed, and are you logged in?)"
    SKIPPED+=("Cloudflare secret GITHUB_TOKEN for $env: npx wrangler secret put GITHUB_TOKEN --env $env")
  fi
done
unset GITHUB_TOKEN
pause

stage "The runbook: the renewal date"
RUNBOOK="$DOCS_DIR/docs/operations.md"
if [[ ! -f "$RUNBOOK" ]]; then
  warn "No $RUNBOOK: clone czAAA/bd-beads-docs next to this repo."
  SKIPPED+=("the renewal date $TOKEN_EXPIRES in the weekly check of docs/operations.md")
else
  say "Writing $TOKEN_EXPIRES into the weekly check's Feedback line, then committing and pushing the docs repo."
  git -C "$DOCS_DIR" pull --rebase --quiet
  # The date sits between "expires on **" and "**" on that one line; a renewal replaces the old date.
  sed -i.bak -E "s/(GITHUB_TOKEN\` .*expires on \*\*)[^*]*(\*\*)/\1$TOKEN_EXPIRES\2/" "$RUNBOOK" && rm -f "$RUNBOOK.bak"
  if grep -q "expires on \*\*$TOKEN_EXPIRES\*\*" "$RUNBOOK"; then
    git -C "$DOCS_DIR" add docs/operations.md
    git -C "$DOCS_DIR" commit --quiet -m "ops: the feedback GITHUB_TOKEN expires on $TOKEN_EXPIRES" || note "nothing new to commit"
    git -C "$DOCS_DIR" push --quiet && printf '  %s✓ pushed%s the renewal date\n' "$GREEN" "$RESET"
  else
    warn "Could not find the Feedback line in $RUNBOOK."
    SKIPPED+=("the renewal date $TOKEN_EXPIRES in the weekly check of docs/operations.md")
  fi
fi
pause

finish
say "Renew the token before $TOKEN_EXPIRES: run this wizard again."
